<script lang="ts">
    // Синхронна помилка для тестування Error Boundary
    // Викликається під час рендерингу, тому svelte:boundary її перехопить
    function triggerError(): never {
        throw new Error(
            "🧪 Це тестова помилка для перевірки Error Boundary! Все працює коректно.",
        );
    }

    // Викликаємо помилку під час ініціалізації скрипта
    triggerError();
</script>

<h1>Ця сторінка ніколи не відобразиться</h1>
